    prismP(B.p(TS), [[21.5, -8.6], [27.6, -8.6], [27.6, 8.6], [21.5, 8.6]], 8.6, 9.6, true, true);
    karahafuP(B.p(RF), B.p(WL), 24.6, 0, 19.5, 7.6, 9.6, 3.0, -HP);
