// ---------------------------------------------------------------- Minato towers on their OSM footprints
const towerLT = {m:1, c:'#d6e4ff', k:0.6};
// Tokyo Midtown Tower (SOM / Nikken Sekkei, 2007): 248.1 m to the roof, 54 floors (en.wikipedia). A tall prism with notched
