// Roppongi Hills Mori Tower (KPF, 2003): 238 m roof, 54 floors, the observation floors at 52F (Tokyo City View) and the
// Mori Art Museum at 53F under the roof deck (en.wikipedia). Curved, overlapping facade plates over a flared base; the shaft
// tapers a little; a dark glazed crown band.
LANDMARKS.tyroppongimori = {zh:'六本木新城森大厦', en:'Roppongi Hills Mori Tower', cat:'new', r:62, h:238, lt:towerLT,
  build(){
    const K = 'tyroppongimori', g = new THREE.Group(), F = frameG(g, K), gf = gL(K), B = mkB(), P = FP(K);
    const GA = {c:'#64737e', ds:true, m:1, fh:4.4, cw:3.0}, GB = {c:'#8d989f', ds:true, m:1, fh:4.4, cw:3.0}, MU = {c:'#c9ced1', ds:true}, CR = {c:'#34414b', ds:true, glow:'#ffe2b5', gk:0.75}, RF = {c:'#a3a8ab', ds:true}, LB = {c:'#4a565e', ds:true, glow:'#ffe6c0', gk:0.5};
    plinthP(B.p(RF), P, gf, 0.3);
    const prof = y => { const s = y < 14 ? 1.0 : y < 26 ? lerp(1.0, 0.86, (y - 14)/12) : lerp(0.86, 0.75, (y - 26)/190); return [s, s, 0, 0]; };
    const T = LT(P, 120, prof);
    // the flared base (lobby levels)
    T.skin(B.p(LB), [0.3, 14]); T.skin(B.p(RF), [14, 26]);
    // shaft in 12 curved plates of two glass tones (the overlapping 'armour' plates), the seams as deep fins
    const ys = [26]; for (let y = 34; y < 216; y += 8) ys.push(y); ys.push(216);
    const secs = ys.map(y => T.at(y));
    for (let i = 0; i < 120; i++){ const o = B.p(Math.floor(i/10) % 2 ? GA : GB), j = (i + 1) % 120; for (let k = 0; k < ys.length - 1; k++) quadP(o, secs[k][i], secs[k][j], secs[k+1][j], secs[k+1][i]); }
    T.bands(B.p(MU), 26, 216, 4.4, 0.45, 0.1);
    T.mulls(B.p(MU), ys, 10, 0.9, 1.1);
    // crown: dark glass band of the observation / museum floors, the roof deck rim
    const prof2 = y => { const s = y < 216 ? 0.75 : y < 220 ? lerp(0.75, 0.735, (y - 216)/4) : 0.735; return [s, s, 0, 0]; };
    const T2 = LT(P, 120, prof2);
    T2.skin(B.p(MU), [216, 218.5]); T2.skin(B.p(CR), [218.5, 232]); T2.skin(B.p(MU), [232, 236.5]);
    { const T3 = LT(P, 120, () => [0.7, 0.7, 0, 0]); T3.skin(B.p(RF), [236.5, 238]); T3.cap(B.p(RF), 238); T.cap(B.p(RF), 236.6); }
    T2.mulls(B.p(MU), [218.5, 232], 4, 0.25, 0.3);
    { const o = B.p(AV), top = LT(P, 12, () => [0.69, 0.69, 0, 0]).at(238.4); for (const p of top) avP(o, p[0], p[1], p[2]); }
    B.flush(F); return g; }};
place('tyroppongimori');

// Azabudai Hills Mori JP Tower (Pelli Clarke & Partners, 2023): 325.2 m, 64 floors, Japan's tallest building (en.wikipedia).
// A softly rounded square plan that tapers in a gentle curve to a rounded crown; fine white vertical mullions.
LANDMARKS.tyazabudai = {zh:'麻布台之丘森JP塔', en:'Azabudai Hills Mori JP Tower', cat:'new', r:50, h:325.2, lt:{m:1, c:'#e2ecff', k:0.65},
  build(){
    const K = 'tyazabudai', g = new THREE.Group(), F = frameG(g, K), gf = gL(K), B = mkB(), P = FP(K);
    const GL = {c:'#a7b7c2', ds:true, m:1, fh:5.0, cw:2.0}, MU = {c:'#f0f2f2', ds:true}, LB = {c:'#5f6c74', ds:true, glow:'#ffe6c0', gk:0.5}, RF = {c:'#c9cdd0', ds:true}, CRN = {c:'#dfe7ec', ds:true, m:0, lc:'#eef4ff', lk:1.2};
    plinthP(B.p(RF), P, gf, 0.3);
    const sc = y => 1 - 0.36*Math.pow(Math.min(1, y/323), 2.1);
    const T = LT(P, 112, y => [sc(y)*0.985, sc(y)*0.985, 0, 0]);
    T.skin(B.p(LB), [0.3, 16]);
    const ys = [16]; for (let y = 26; y < 306; y += 10) ys.push(y); ys.push(306);
    T.skin(B.p(GL), ys);
    T.bands(B.p(MU), 16, 306, 5.0, 0.35, 0.08);
    T.mulls(B.p(MU), ys, 2, 0.32, 0.45);
    // rounded crown: the plan keeps shrinking faster over the last floors
    const cy = [306, 311, 315, 318.5, 321, 323.1], cs = [1, 0.97, 0.92, 0.85, 0.74, 0.55];
    T.mulls(B.p(MU), [306, 311, 315], 2, 0.32, 0.45);
    loftP(B.p(CRN), cy.map((y, k) => T.at(y).map(p => [T.C[0] + (p[0] - T.C[0])*cs[k], y, T.C[1] + (p[2] - T.C[1])*cs[k]])), true);
    { const c = T.C; LCylD(F, 0.35, 0.6, 2.2, c[0], 323.0, c[1], RF, 8); boxP(B.p(AV), 1.0, 1.0, 1.0, c[0], 325.2, c[1], 0); }
    B.flush(F); return g; }};
place('tyazabudai');

// Toranomon Hills Mori Tower (Nihon Sekkei, 2014): 255.5 m / 52 floors (en.wikipedia 255 m; OSM roof 247 m), built over the
// Loop Road No. 2 tunnel. A rounded-square shaft (the OSM tower part), the upper floors drawing in to a finned crown;
// the podium on the rest of the footprint (offices, the Oval Plaza's green roof).
LANDMARKS.tytoranomon = {zh:'虎之门之丘森大厦', en:'Toranomon Hills Mori Tower', cat:'new', r:96, h:255.5, lt:towerLT,
  build(){
    const K = 'tytoranomon', g = new THREE.Group(), F = frameG(g, K), gf = gL(K), B = mkB(), P = FP(K), TW = FP(K, 'tw');
    const GL = {c:'#7a8d9a', ds:true, m:1, fh:4.75, cw:2.4}, MU = {c:'#d3d8db', ds:true}, LB = {c:'#55626b', ds:true, glow:'#ffe6c0', gk:0.5}, RF = {c:'#a9aeb1', ds:true}, GR = {c:'#6f8f55', ds:true}, PD = {c:'#c9c3b6', ds:true, m:1, fh:4.2, cw:3.2};
    plinthP(B.p(RF), P, gf, 0.3);
    // podium (two levels over the tunnel portal side) with a planted roof
    prismP(B.p(PD), P, 0.3, 6.6, true, true); flatP(B.p(GR), P, 6.6); bandsP(B.p(LB), P, 1.0, 6.6, 3.3, 2.0, 0.08);
    const c = cenP(TW), prof = y => { const k = y < 200 ? 1 : lerp(1, 0.86, (y - 200)/47); return [k, lerp(1, k, 0.5), 0, 0]; };
    const T = LT(TW, 96, prof, c);
    T.skin(B.p(LB), [0.3, 12]);
    const ys = [12]; for (let y = 20; y < 247; y += 9) ys.push(y); ys.push(247);
    T.skin(B.p(GL), ys); T.bands(B.p(MU), 12, 247, 4.75, 0.5, 0.08); T.mulls(B.p(MU), ys, 2, 0.3, 0.5);
    T.cap(B.p(RF), 247);
    // the crown: fins rising 8.5 m above the roof round an inset plant screen
    const T2 = LT(TW, 48, () => [0.86, 0.93, 0, 0], c); T2.mulls(B.p(MU), [247, 255.5], 1, 0.4, 0.6);
    { const T3 = LT(TW, 48, () => [0.74, 0.8, 0, 0], c); T3.skin(B.p(RF), [247, 252]); T3.cap(B.p(RF), 252);
      for (const p of LT(TW, 8, () => [0.86, 0.93, 0, 0], c).at(255.7)) avP(B.p(AV), p[0], p[1], p[2]); }
    B.flush(F); return g; }};
place('tytoranomon');

// Toranomon Hills Station Tower (OMA / Shohei Shigematsu, 2023): 266 m, 49 floors (en.wikipedia). "Carved, bisected and shifted":
// a central band sandwiched by two slabs in inverted symmetry - the north slab wide at the base and narrowing to the top, the
// south slab narrow at the base and widening as it rises (OMA via metalocus). TOKYO NODE on the top floors (45-49F) with a roof garden.
LANDMARKS.tytoranomonst = {zh:'虎之门之丘车站大厦', en:'Toranomon Hills Station Tower', cat:'new', r:86, h:266, lt:towerLT,
  build(){
    const K = 'tytoranomonst', g = new THREE.Group(), F = frameG(g, K), gf = gL(K), B = mkB(), P = FP(K);
    const GN = {c:'#8ea2ae', ds:true, m:1, fh:5.0, cw:2.4}, GS = {c:'#9fb0b9', ds:true, m:1, fh:5.0, cw:2.4}, BAND = {c:'#414e58', ds:true, m:1, fh:5.0, cw:2.0}, MU = {c:'#dde1e3', ds:true}, LB = {c:'#56646d', ds:true, glow:'#ffe6c0', gk:0.55}, RF = {c:'#b3b7b9', ds:true}, TOP = {c:'#c5d2d8', ds:true, glow:'#fff0d8', gk:0.45}, GR = {c:'#6a8b52', ds:true};
    plinthP(B.p(RF), P, gf, 0.3);
    // podium: the station atrium levels on the whole site
    prismP(B.p(LB), offP(P, 1.0), 0.3, 18.0); bandsP(B.p(MU), offP(P, 1.0), 4.5, 18, 4.5, 0.5, 0.08); mullP(B.p(MU), offP(P, 1.0), 0.3, 18, 4.0, 0.3, 0.06, 0.3);
    // the two slabs and the central band (u along the tower, -v = north)
    const U = 41, yb = 18, yt = 246;
    const nS = y => { const t = (y - yb)/(yt - yb); return [-lerp(27, 15, t), -4.2]; };      // north slab v range
    const sS = y => { const t = (y - yb)/(yt - yb); return [-1.0, lerp(7, 19, t)]; };        // south slab v range
    const slab = (o, fv, ua, ub) => { const ys = [yb]; for (let y = yb + 19; y < yt; y += 19) ys.push(y); ys.push(yt);
      const secs = ys.map(y => { const [v0, v1] = fv(y); return [[ua, y, v0], [ub, y, v0], [ub, y, v1], [ua, y, v1]]; }); loftP(o, secs, true);
      const MO = B.p(MU); for (let y = yb + 5; y < yt; y += 5){ const [v0, v1] = fv(y), [w0, w1] = fv(Math.min(yt, y + 0.45)); quadP(MO, [ua - 0.08, y, v0 - 0.08], [ub + 0.08, y, v0 - 0.08], [ub + 0.08, y + 0.45, w0 - 0.08], [ua - 0.08, y + 0.45, w0 - 0.08]); quadP(MO, [ua - 0.08, y, v1 + 0.08], [ub + 0.08, y, v1 + 0.08], [ub + 0.08, y + 0.45, w1 + 0.08], [ua - 0.08, y + 0.45, w1 + 0.08]); }
      for (let u = ua; u <= ub + 0.01; u += 2.4) for (const side of [0, 1]){ const pts = ys.map(y => { const r = fv(y); return [u, y, side ? r[1] + 0.3 : r[0] - 0.3]; }); for (let k = 0; k < pts.length - 1; k++) segP(MO, pts[k], pts[k + 1], 0.16, 3); } };
    slab(B.p(GN), nS, -U, U); slab(B.p(GS), sS, -U + 3, U - 3);
    prismP(B.p(BAND), [[-U + 6, -4.6], [U - 6, -4.6], [U - 6, -0.6], [-U + 6, -0.6]], yb, yt);
    // TOKYO NODE: the glazed top floors spanning both slabs, roof garden and plant screen
    const top = [[-U - 1.2, -16.2], [U + 1.2, -16.2], [U + 1.2, 20.2], [-U - 1.2, 20.2]];
    prismP(B.p(TOP), top, yt, 262); mullP(B.p(MU), top, yt, 262, 3.0, 0.35, 0.05, 0.4); bandsP(B.p(MU), top, yt, 262, 5.3, 0.6, 0.08);
    edgeP(B.p(MU), top, 262, 0.8, 1.6, 0.1); flatP(B.p(GR), offP(top, 1), 262.1);
    prismP(B.p(RF), [[-18, -8], [18, -8], [18, 8], [-18, 8]], 262, 266);
    for (const p of offP(top, 0.6)) avP(B.p(AV), p[0], 263.8, p[1]); avP(B.p(AV), 0, 266.2, 0, 1.0);
    B.flush(F); return g; }};
place('tytoranomonst');

